import ee, sys, math
ee.Initialize(project='earthsense-436113')

# Geometry: a compact rectangle around ~8 km buffer to keep operations light
lon, lat = -105.503, 35.759
aoi = ee.Geometry.Point([lon, lat]).buffer(8000).bounds()  # ~16x16 km

def mask_s2_sr(img):
    qa = img.select('QA60')
    cloud = qa.bitwiseAnd(1 << 10).neq(0)
    cirrus = qa.bitwiseAnd(1 << 11).neq(0)
    mask = cloud.Or(cirrus).Not()
    return img.updateMask(mask)

def s2_nbr_single(geom, start, end):
    col = (ee.ImageCollection('COPERNICUS/S2_SR')
           .filterBounds(geom)
           .filterDate(start, end)
           .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 80)))
    size = col.size().getInfo()
    if size == 0:
        return size, None, None
    img = ee.Image(col.sort('CLOUDY_PIXEL_PERCENTAGE').first())
    img = mask_s2_sr(img)
    nbr = img.normalizedDifference(['B8','B12']).rename('NBR')
    date = ee.Date(img.get('system:time_start')).format('YYYY-MM-dd').getInfo()
    return size, nbr, date

def mask_landsat_c2(img):
    qa = img.select('QA_PIXEL')
    mask = (qa.bitwiseAnd(1<<1).eq(0)  # dilated cloud
            .And(qa.bitwiseAnd(1<<3).eq(0))  # cloud
            .And(qa.bitwiseAnd(1<<4).eq(0)))  # cloud shadow
    return img.updateMask(mask)

def ls_nbr_single(geom, start, end):
    l8 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2').filterBounds(geom).filterDate(start, end)
    l9 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2').filterBounds(geom).filterDate(start, end)
    col = l8.merge(l9)
    size = col.size().getInfo()
    if size == 0:
        return size, None, None
    img = ee.Image(col.sort('CLOUD_COVER').first())
    img = mask_landsat_c2(img)
    nir = img.select('SR_B5').multiply(0.0000275).add(-0.2)
    sw2 = img.select('SR_B7').multiply(0.0000275).add(-0.2)
    nbr = nir.subtract(sw2).divide(nir.add(sw2)).rename('NBR')
    date = ee.Date(img.get('system:time_start')).format('YYYY-MM-dd').getInfo()
    return size, nbr, date

def summarize_window(geom, start, end, total_count):
    # Try Sentinel-2 first
    s2_size, s2_nbr, s2_date = s2_nbr_single(geom, start, end)
    source, used_imgs, used_date, nbr_img = None, 0, None, None
    if s2_size > 0 and s2_nbr is not None:
        try:
            valid = s2_nbr.reduceRegion(
                reducer=ee.Reducer.count(),
                geometry=geom,
                scale=1000,
                maxPixels=1e9
            ).get('NBR').getInfo()
            valid = 0 if valid is None else int(valid)
            if valid > 0:
                burned_mask = s2_nbr.lt(0.1)
                area = ee.Image.pixelArea().divide(1e6).updateMask(burned_mask).reduceRegion(
                    reducer=ee.Reducer.sum(),
                    geometry=geom,
                    scale=1000,
                    maxPixels=1e9
                ).get('area').getInfo()
                area = 0.0 if area is None else float(area)
                return {'status':'OK','source':'S2','imgs':s2_size,'date':s2_date,'valid':valid,
                        'mask_pct': (0 if total_count==0 else max(0.0,min(100.0,(1 - valid/total_count)*100))),
                        'burn_km2': area}
        except Exception:
            pass

    # Fallback to Landsat
    ls_size, ls_nbr, ls_date = ls_nbr_single(geom, start, end)
    if ls_size == 0 and s2_size == 0:
        return {'status':'C1','source':'None','imgs':0,'date':None,'valid':0,'mask_pct':100.0,'burn_km2':None}
    if ls_size > 0 and ls_nbr is not None:
        try:
            valid = ls_nbr.reduceRegion(
                reducer=ee.Reducer.count(),
                geometry=geom,
                scale=1000,
                maxPixels=1e9
            ).get('NBR').getInfo()
            valid = 0 if valid is None else int(valid)
            if valid == 0:
                return {'status':'C2','source':'L8/9','imgs':ls_size,'date':ls_date,'valid':0,'mask_pct':100.0,'burn_km2':None}
            burned_mask = ls_nbr.lt(0.1)
            area = ee.Image.pixelArea().divide(1e6).updateMask(burned_mask).reduceRegion(
                reducer=ee.Reducer.sum(),
                geometry=geom,
                scale=1000,
                maxPixels=1e9
            ).get('area').getInfo()
            if area is None or (isinstance(area,float) and (math.isnan(area) or math.isinf(area))):
                return {'status':'C3','source':'L8/9','imgs':ls_size,'date':ls_date,'valid':valid,
                        'mask_pct': (0 if total_count==0 else max(0.0,min(100.0,(1 - valid/total_count)*100))),
                        'burn_km2':None}
            return {'status':'OK','source':'L8/9','imgs':ls_size,'date':ls_date,'valid':valid,
                    'mask_pct': (0 if total_count==0 else max(0.0,min(100.0,(1 - valid/total_count)*100))),
                    'burn_km2': float(area)}
        except Exception:
            return {'status':'C3','source':'L8/9','imgs':ls_size,'date':ls_date,'valid':0,'mask_pct':100.0,'burn_km2':None}

    # If S2 existed but had 0 valid pixels after masking
    if s2_size > 0:
        return {'status':'C2','source':'S2','imgs':s2_size,'date':s2_date,'valid':0,'mask_pct':100.0,'burn_km2':None}

    return {'status':'C1','source':'None','imgs':0,'date':None,'valid':0,'mask_pct':100.0,'burn_km2':None}

try:
    win1 = ('2022-04-17', '2022-04-21')
    win2 = ('2022-04-21', '2022-04-25')

    total_count = ee.Image.constant(1).rename('one').reduceRegion(
        reducer=ee.Reducer.count(),
        geometry=aoi,
        scale=1000,
        maxPixels=1e9
    ).get('one').getInfo()
    total_count = 0 if total_count is None else int(total_count)

    res1 = summarize_window(aoi, win1[0], win1[1], total_count)
    res2 = summarize_window(aoi, win2[0], win2[1], total_count)

    print(f"Location: (-105.503, 35.759), AOI ~16x16 km")
    print(f"Total 1km cells in AOI: {total_count}")
    print(f"Win1 {win1[0]}..{win1[1]} -> {res1['status']}, Src:{res1['source']}, ImgCnt:{res1['imgs']}, UsedDate:{res1['date']}, Valid:{res1['valid']}, Mask%:{res1['mask_pct']:.1f}%, Burned km2:{res1['burn_km2']}")
    print(f"Win2 {win2[0]}..{win2[1]} -> {res2['status']}, Src:{res2['source']}, ImgCnt:{res2['imgs']}, UsedDate:{res2['date']}, Valid:{res2['valid']}, Mask%:{res2['mask_pct']:.1f}%, Burned km2:{res2['burn_km2']}")

    # If any window failed, report the most specific failure
    if res1['status'] != 'OK' or res2['status'] != 'OK':
        tag = 'D'
        for code in ['C1', 'C2', 'C3']:
            if res1['status'] == code or res2['status'] == code:
                tag = code
                break
        print(tag)
        sys.exit(0)

    a1 = float(res1['burn_km2'])
    a2 = float(res2['burn_km2'])
    diff = a2 - a1
    print(f"Burned Area km2: {a1:.2f} -> {a2:.2f} (Δ {diff:.2f})")

    if (math.isnan(a1) or math.isnan(a2) or math.isinf(a1) or math.isinf(a2)):
        print("C3")
    elif diff > 0.5:
        print("A")
    else:
        print("B")

except Exception as e:
    print(f"Error: {str(e)[:120]}")
    print("D")
